function makeWaveSlab(pixelPoints, color, z, depth = 0.6, segments = 5) {
  const shape = new THREE.Shape();
  const pts = pixelPoints.map(([x, y]) => px2v(x, y));
  shape.moveTo(pts[0].x, pts[0].y);
  shape.splineThru(pts.slice(1));
  shape.closePath();
  const geo = new THREE.ExtrudeGeometry(shape, { depth, bevelEnabled: true, bevelThickness: 0.15, bevelSize: 0.06, bevelSegments: 1, curveSegments: segments });
